#!/usr/bin/env node
'use strict';
// Short phased plan, generated by SCRIPT from findings.json (no agent): .ui-guard/plan.md (≤ ~150 lines, human),
// .ui-guard/plan.json (machine: every phase's files + finding IDs, read by /ui-guard:fix), .ui-guard/renames.md.
// Safe order: foundation → common → layouts → pages → generic/elements, numbered 1..N. A phase has at most
// MAX_FILES files OR MAX_FINDINGS findings (whichever is hit first), split by top-level app folder, then feature folder.
const path = require('path');
const u = require('./lib/util');
const project = require('./lib/project');
const libs = require('./lib/libclasses');
const domains = require('./lib/domains');
const route = require('./route-files');

const HELP = `plan.js — build one domain's plan.md / plan.json (+ renames.md for scss) from its findings.json (0 tokens).
Usage: node plan.js --domain scss|access|lang|safe [--root <dir>]   (re-running keeps each unchanged phase's status)
       node plan.js render --domain <d> [--root <dir>]              re-render plan.md from plan.json (after a status change)
The scss plan ALWAYS starts with Foundation A (structure) and Foundation B (move the global stylesheets) — run by scripts.`;

const MAX_FILES = 15, MAX_FINDINGS = 300, MAX_LINES = 150;
const AREAS = [
  { key: 'foundation-a', name: 'Foundation A — Structure', kind: 'foundation-structure', domains: ['scss'], why: 'Every later fix uses our segments, tools, settings, theme files and the one entry, so they must exist first.', how: 'Script: create the missing segment/tools/settings/theme/entry files from the templates (no value changes; resets as empty files), add includePaths, the entry and the theme <link>s.' },
  { key: 'foundation-b', name: 'Foundation B — Move', kind: 'foundation-move', domains: ['scss'], why: 'The existing global stylesheets must live in our segments before single files are fixed.', how: 'Script: move every rule of the global stylesheets into its segment file in the same cascade order, update the entry and angular.json, delete the emptied files; proven by compiling before/after. What cannot be proven goes to the fixer.' },
  { key: 'foundation', name: 'Foundation — settings, tools, theme', domains: ['scss'], why: 'Everything else uses the settings, tools, theme tokens and build config.', how: 'Normalize settings/tools/theme names and config without changing any value.' },
  { key: 'global', name: 'Global — index.html, config, translations', domains: ['access', 'lang', 'safe'], why: 'index.html, the config and the translation files are used by every page.', how: 'Fix the global files first; every later phase relies on them.' },
  { key: 'common', name: 'Common', why: 'Shared components, styles and translations are used by many pages; fixing them once removes repeats later.', how: 'Fix shared blocks and their usages in every template/TS; keep the current look.' },
  { key: 'layouts', name: 'Layouts', why: 'The shell (header, menu, footer) is on every page, so it comes before single pages.', how: 'Fix the layout files; 0-pixel screenshot proof.' },
  { key: 'pages', name: 'Pages', why: 'Page-only code is fixed after the shared pieces it depends on.', how: "Fix each page group's files; 0-pixel screenshot proof." },
  { key: 'generic', name: 'Generic + Elements', domains: ['scss'], why: 'Global resets touch every page, so they are fixed last, with the full visual pass.', how: 'Fix the generic/elements segment files so the result is identical; no new resets.' },
];
const FAMILY = { STYLE: 'SCSS architecture & classes (STYLE)', LANG: 'translation (LANG)', SAFE: 'security (SAFE)', ACCESS: 'accessibility (ACCESS)', LINT: 'other lint (LINT)' };

/** Global stylesheets: not a component style and not in the scss root → Foundation B, never "Pages". */
function areaOf(file, profile, ctx = {}) {
  const sr = project.scssRoot(profile);
  const isStyle = /\.s?css$/.test(file);
  if (ctx.domain === 'scss') {
    if (isStyle && !file.startsWith(sr + '/') && !(ctx.componentStyles && ctx.componentStyles.has(file)) && !/^src\/app\/.*\.component\.s?css$/.test(file) && !/^src\/assets\/themes\//.test(file)) return 'foundation-b';
  }
  if (file === 'angular.json' || file === 'src/index.html' || /^src\/environments\//.test(file) || /^src\/assets\/themes\//.test(file) || /^src\/assets\/config\//.test(file)) return ctx.domain === 'scss' ? 'foundation' : 'global';
  if (project.isTranslationPath(file, profile)) return ctx.domain === 'scss' ? 'common' : 'global';
  if (file.startsWith(sr + '/')) {
    const seg = file.slice(sr.length + 1).split('/')[0];
    if (['settings', 'tools', 'theme', 'packages'].includes(seg) || file === sr + '/style.scss') return 'foundation';
    if (['generic', 'elements'].includes(seg)) return 'generic';
    if (seg === 'layout') return 'layouts';
    if (seg === 'pages') return 'pages';
    return 'common';
  }
  const explicit = project.roleMap(profile).find((r) => u.globMatch(r.glob, file));
  if (explicit) return explicit.role === 'layout' ? 'layouts' : explicit.role === 'page' ? 'pages' : 'common';
  if (/^src\/app\/(shared|core|common)\//.test(file)) return 'common';
  if (/(^|\/)(layout|layouts|shell)[^/]*\//.test(file)) return 'layouts';
  return 'pages';
}

/** Folder parts used for grouping: app-relative (src/app/<top>/<feature>/…) or scss-root-relative. */
function folderParts(file, profile) {
  const sr = project.scssRoot(profile) + '/';
  const rel = file.startsWith('src/app/') ? file.slice(8) : file.startsWith(sr) ? file.slice(sr.length) : file;
  return rel.split('/').slice(0, -1);
}

const fits = (files, n) => files.length <= MAX_FILES && n <= MAX_FINDINGS;

/**
 * Split units [{file,n,parts}] into parts that respect the limits: by top-level folder first, then the next folder
 * level, … ; adjacent small groups are merged while they fit; as a last resort a folder is chunked by file order.
 * Returns [{ files:[unit], label }].
 */
function pack(units, depth, label) {
  const total = units.reduce((s, x) => s + x.n, 0);
  if (fits(units, total)) return [{ units, labels: [label] }];
  const groups = new Map();
  for (const x of units) { const k = x.parts[depth] === undefined ? null : x.parts[depth]; (groups.get(k) || groups.set(k, []).get(k)).push(x); }
  const keys = [...groups.keys()].sort((a, b) => (a === null ? -1 : b === null ? 1 : a < b ? -1 : 1));
  if (keys.length === 1 && keys[0] === null || units.every((x) => x.parts.length <= depth)) return chunk(units, label);
  let parts = [];
  for (const k of keys) parts.push(...pack(groups.get(k), depth + 1, k === null ? label : k));
  // merge adjacent parts while they still fit
  const merged = [];
  for (const p of parts) {
    const last = merged[merged.length - 1];
    if (last) {
      const all = last.units.concat(p.units);
      if (fits(all, all.reduce((s, x) => s + x.n, 0))) { last.units = all; last.labels = [...new Set(last.labels.concat(p.labels))]; continue; }
    }
    merged.push({ units: p.units.slice(), labels: p.labels.slice() });
  }
  return merged;
}

function chunk(units, label) {
  const out = [];
  let cur = [], n = 0;
  for (const x of units) {
    if (cur.length && (cur.length + 1 > MAX_FILES || n + x.n > MAX_FINDINGS)) { out.push({ units: cur, labels: [label] }); cur = []; n = 0; }
    cur.push(x); n += x.n;
  }
  if (cur.length) out.push({ units: cur, labels: [label] });
  if (out.length > 1) out.forEach((p, i) => { p.labels = [`${label} ${i + 1}/${out.length}`]; });
  return out;
}

function labelText(labels) {
  const l = labels.filter(Boolean);
  if (!l.length) return null;
  return l.length <= 2 ? l.join(' + ') : `${l[0]} + ${l.length - 1} more`;
}

function buildPhases(findings, profile, ctx) {
  const confirmed = findings.filter((f) => f.status === 'confirmed');
  const byArea = {};
  for (const f of confirmed) { const a = f.ruleId === 'STYLE-48' ? style48Area(f) : areaOf(f.file, profile, ctx); (byArea[a] = byArea[a] || []).push(f); }
  const phases = [];
  for (const a of AREAS.filter((x) => !x.domains || x.domains.includes(ctx.domain))) {
    const list = byArea[a.key] || [];
    if (a.kind) { // Foundation A/B: one phase each, ALWAYS present for scss (scripts decide what is left to do)
      phases.push({ area: a, label: null, files: [...new Set(list.map((f) => f.file))].sort(), findings: list });
      continue;
    }
    if (!list.length) continue;
    const perFile = {};
    for (const f of list) perFile[f.file] = (perFile[f.file] || 0) + 1;
    const units = Object.keys(perFile).sort().map((file) => ({ file, n: perFile[file], parts: folderParts(file, profile) }));
    const parts = pack(units, 0, null);
    parts.forEach((p) => {
      const set = new Set(p.units.map((x) => x.file));
      phases.push({ area: a, label: parts.length > 1 ? labelText(p.labels) : null, files: p.units.map((x) => x.file), findings: list.filter((f) => set.has(f.file)) });
    });
  }
  return phases;
}
const style48Area = (f) => (/^Misplaced/.test(f.message || '') ? 'foundation-b' : 'foundation-a');

function topRules(fs_, n) {
  const byRule = {};
  for (const f of fs_) byRule[f.ruleId] = (byRule[f.ruleId] || 0) + 1;
  const top = Object.entries(byRule).sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1));
  return { top: top.slice(0, n), more: top.slice(n) };
}

function render(plan, findingsById) {
  const ph = plan.phases;
  const all = ph.flatMap((p) => p.findings.map((id) => findingsById[id]).filter(Boolean));
  const fam = {};
  for (const f of all) { const k = f.ruleId.split(/[-:]/)[0]; fam[k] = (fam[k] || 0) + 1; }
  const famOrder = Object.keys(fam).sort((a, b) => fam[b] - fam[a]);
  const sev = (s) => all.filter((f) => f.severity === s).length;
  const d = plan.domain || 'scss';
  const head = [
    `# ui-guard ${d} plan`, '',
    `This project does not follow our ${d} rules in these areas: ${famOrder.map((k) => FAMILY[k] || k).join(', ') || 'none found'}.`,
    `Total: ${new Set(all.map((f) => f.file)).size} files, ${all.length} findings (${sev('error')} errors, ${sev('warning')} warnings, ${sev('info')} info).`,
    `${ph.length} phases in a safe order, each at most ${MAX_FILES} files or ${MAX_FINDINGS} findings. \`/ui-guard:fix ${d}\` runs them all, back to back, without asking; \`/ui-guard:fix ${d} <n>\` runs one.`,
    d === 'scss' ? 'Foundation A and B always come first and are done by scripts (0 tokens); mechanical fixes in every later phase are scripts too — the agent gets only what needs judgment.' : 'Scripts first; the fixer agent gets only the findings that need judgment.',
    'Images and assets are not part of this plan — `/ui-guard:assets` checks referenced files exist.', '',
  ];
  const foot = [`Full file lists and finding IDs per phase: \`.ui-guard/${d}/plan.json\` · all findings by file: \`write-report.js --domain ${d} --details\`.`];
  const routeText = (p) => `${(p.routes || []).join(', ') || 'chosen when the phase runs'}${p.weakCoverage ? ' — weak coverage: these pages are checked by eye' : ''}`;
  const full = [];
  const seen = {};
  ph.forEach((p) => {
    const fs_ = p.findings.map((id) => findingsById[id]).filter(Boolean);
    const { top, more } = topRules(fs_, 5);
    const a = AREAS.find((x) => x.key === p.area) || AREAS[3];
    full.push(`## Phase ${p.id} of ${ph.length} — ${p.title} · ${p.status}`, '');
    if (seen[p.area]) full.push(`Why/how: same as phase ${seen[p.area]}.`);
    else { full.push(`Why now: ${p.why || a.why}`); seen[p.area] = p.id; }
    full.push(`Files: ${p.files.length} · findings: ${fs_.length} · e.g. ${p.files.slice(0, 2).map((f) => '`' + f + '`').join(', ')}`);
    full.push(`Top rules: ${top.map(([id, n]) => `${id} ×${n}`).join(', ')}${more.length ? ` (+${more.length} more ×${more.reduce((s, [, n]) => s + n, 0)})` : ''}`);
    if (seen[p.area] === p.id) full.push(`How: ${p.how || a.how}`);
    full.push(`Screenshot routes: ${routeText(p)}`, '');
  });
  if (head.length + full.length + foot.length <= MAX_LINES) return [...head, ...full, ...foot].join('\n') + '\n';
  // many phases: one table row per phase keeps plan.md under the limit
  const rows = ['| Phase | Area | Files | Findings | Top rules | Routes |', '|---|---|---|---|---|---|'];
  ph.forEach((p) => {
    const fs_ = p.findings.map((id) => findingsById[id]).filter(Boolean);
    const { top } = topRules(fs_, 5);
    rows.push(`| ${p.id} of ${ph.length} | ${p.title} · ${p.status} | ${p.files.length} | ${fs_.length} | ${top.map(([id, n]) => `${id} ×${n}`).join(', ')} | ${(p.routes || []).join(' ') || '—'}${p.weakCoverage ? ' (weak)' : ''} |`);
  });
  const why = AREAS.filter((a) => ph.some((p) => p.area === a.key)).map((a) => `- **${a.name}:** ${a.why} ${a.how}`);
  return [...head, ...rows, '', ...why, '', ...foot].join('\n') + '\n';
}

/** The top-level block class (".x" alone) whose rule nests every occurrence of `.cls` in that stylesheet, or null. */
function parentBlock(root, file, cls) {
  if (!/\.s?css$/.test(String(file))) return null;
  const text = (u.readText(u.fromPosix(root, file)) || '').replace(/\/\*[\s\S]*?\*\/|\/\/[^\n]*/g, (m) => m.replace(/[^\n]/g, ' '));
  const re = new RegExp(`\\.${cls.replace(/[-]/g, '\\-')}(?![\\w-])`, 'g');
  let block = null, m;
  while ((m = re.exec(text))) {
    const stack = [];
    let sel = '';
    for (let i = 0; i < m.index; i++) {
      const ch = text[i];
      if (ch === '{') { stack.push(sel.trim()); sel = ''; } else if (ch === '}') { stack.pop(); sel = ''; } else if (ch === ';') sel = ''; else sel += ch;
    }
    const top = stack.find((s) => !s.startsWith('@'));
    const b = top && /^\.([\w-]+)$/.exec(top);
    if (!b || b[1] === cls) return null; // top level somewhere, or not under a single plain block class
    if (block && block !== b[1]) return null;
    block = b[1];
  }
  return block;
}

/** renames.md from findings: normal classes → rows; library classes → "kept"; project state classes → "(decide)". */
function renames(findings, phaseOf, root, ctx, filePhase = {}) {
  const idxFile = path.join(project.paths(root).scan, 'class-usage.json');
  if (!u.exists(idxFile) && !u.exists(path.join(domains.paths(root, 'scss').scan, 'class-usage.json'))) { try { require('./class-usage').run(root, project.readProfile(root)); } catch { /* the index only improves the names */ } }
  const usage = u.readJSON(idxFile, null) || u.readJSON(path.join(domains.paths(root, 'scss').scan, 'class-usage.json'), null);
  const count = (c) => (usage && usage[c] ? usage[c].length : null);
  const rows = new Map(), kept = new Map();
  const classes = new Map(); // project class without prefix → { phases, finds }; named after the loop (every class gets a real name)
  const profile = project.readProfile(root);
  for (const f of findings.filter((x) => x.status === 'confirmed')) {
    let m;
    const cls = libs.style01Class(f);
    if (cls) {
      const why = libs.libraryReason(cls, ctx);
      if (why) { if (!kept.has(cls)) kept.set(cls, { reason: why, uses: count(cls), phase: phaseOf[f.id] }); continue; }
      const rec = classes.get(cls) || classes.set(cls, { phases: [], finds: [] }).get(cls);
      if (phaseOf[f.id]) rec.phases.push(phaseOf[f.id]);
      rec.finds.push(f);
    } else if (f.ruleId === 'STYLE-09' && (m = /Token `(--[\w-]+)`.*typo of `([\w-]+)`/.exec(f.message))) {
      const old = m[1];
      const parts = old.slice(2).split('-');
      const fixed = '--' + parts.map((p) => (p.length >= 4 && !/\d/.test(p) ? m[2] : p)).join('-');
      if (!rows.has('token:' + old)) rows.set('token:' + old, { old, neu: fixed === old ? '(decide)' : fixed, reason: 'STYLE-09 — typo; value unchanged', phase: phaseOf[f.id], uses: null });
    } else if (f.ruleId === 'STYLE-09' && (m = /Token `(--[\w-]+)` named by appearance/.exec(f.message))) {
      if (!rows.has('token:' + m[1])) rows.set('token:' + m[1], { old: m[1], neu: '(decide: role or --family-step)', reason: 'STYLE-09 — named by appearance; value unchanged', phase: phaseOf[f.id], uses: null });
    }
  }
  // every project class gets a REAL name (no "decide" rows, no question): prefix from the defining file's role, kebab-case, BEM element
  // when it is styled only inside another block. The row runs in the LAST phase that holds one of its files, so all definers are done.
  const taken = new Set([...Object.keys(usage || {}), ...kept.keys()]);
  const names = require('./lib/class-names');
  for (const [cls, rec] of [...classes].sort((a, b) => (a[0] < b[0] ? -1 : 1))) {
    const list = (usage && usage[cls]) || [];
    const defs = list.filter((x) => x.how === 'definition');
    const uses = list.filter((x) => x.how !== 'definition');
    const state = libs.isStateClass(cls) || names.isCodeToggled(uses);
    const defFile = (defs.find((d) => /\.s?css$/.test(d.file) && !/(^|\/)theme\//.test(d.file)) || defs[0] || {}).file;
    const outer = !state && defFile ? parentBlock(root, defFile, cls) : null;
    const p = names.propose(cls, { profile, defs, uses, outer, taken, isState: state });
    const phase = Math.max(0, ...rec.phases, ...defs.map((d) => filePhase[d.file] || 0)) || null;
    rows.set('class:' + cls, { old: '.' + cls, neu: '.' + p.name, reason: p.reason, phase, uses: list.length || null });
  }
  const L = ['# ui-guard renames', '', 'Generated by script from findings.json. Every class gets its AXIS name here (role prefix from the defining file, kebab-case, BEM element);',
    'the fixer applies a row in its phase, updating every usage (SCSS, templates, TS). Token values never change. Nothing here needs the developer: a row is changed only by hand-editing this file.', '',
    '| Old | New | Reason | Phase | Usages |', '|---|---|---|---|---|'];
  for (const r of [...rows.values()].sort((a, b) => (a.phase || 99) - (b.phase || 99) || (a.old < b.old ? -1 : 1))) L.push(`| \`${r.old}\` | ${r.neu.startsWith('(') ? r.neu : '`' + r.neu + '`'} | ${r.reason} | ${r.phase || '—'} | ${r.uses == null ? '?' : r.uses} |`);
  if (!rows.size) L.push('| — | — | no scriptable renames found | — | — |');
  L.push('', '## Library classes (kept as they are)', '',
    'These classes belong to a library (Bootstrap, PrimeNG, ngx-*, a dependency\'s CSS, or the project only styles them under a library selector / `::ng-deep`).',
    'They are NOT renamed — renaming would break the library\'s styling — and they raise no STYLE-01 finding.', '');
  if (kept.size) {
    L.push('| Class | Why it is kept | Usages |', '|---|---|---|');
    for (const [c, r] of [...kept.entries()].sort((a, b) => (a[0] < b[0] ? -1 : 1))) L.push(`| \`.${c}\` | ${r.reason} | ${r.uses == null ? '?' : r.uses} |`);
  } else L.push('None found.');
  L.push('', 'Not scriptable (needs judgment, not listed): class renames found only by AI rules (STYLE-02/03), token moves between files.');
  return { text: L.join('\n') + '\n', count: rows.size, kept: kept.size };
}

function run(root, domain) {
  const dom = domains.get(domain);
  const dp = domains.paths(root, dom.name);
  const profile = project.readProfile(root);
  const raw = (u.readJSON(dp.findings, []) || []);
  const lctx = libs.context(root, profile);
  const all = dom.name === 'scss' ? libs.splitFindings(raw, lctx).rest : raw; // STYLE-01 on library classes is not a finding
  // fix works only on the domain's OPEN findings: a finding the ledger holds as needs-decision or skipped (same file + stable key,
  // file unchanged) is not planned again until the developer decides or runs `/ui-guard:scan <domain> --rescan`
  const L = require('./lib/ledger');
  const { ledger } = L.load(root);
  const parked = new Set();
  for (const [rel, e] of Object.entries(ledger.files)) for (const f of ((e.domains[dom.name] || {}).findings || [])) if (f.status === 'needs-decision' || f.status === 'skipped') parked.add(`${rel}|${f.fingerprint}`);
  const findings = parked.size ? all.filter((f) => !parked.has(`${f.file}|${f.fingerprint}`)) : all;
  const byId = Object.fromEntries(findings.map((f) => [f.id, f]));
  const old = u.readJSON(dp.planJson, { phases: [] });
  const entries = route.routeMap(root);
  // screenshot routes for global phases: REAL content routes of the app (utility pages like /no-connection come last)
  const real = route.realRoutes(root, entries);
  const defaults = ((profile.screenshots && profile.screenshots.routes) || real.filter((r) => !route.UTILITY_ROUTE.test(r)).concat(real.filter((r) => route.UTILITY_ROUTE.test(r)))).slice(0, 3);
  const ctx = { domain: dom.name, componentStyles: dom.name === 'scss' ? require('./foundation').componentStyles(root) : new Set() };
  const built = buildPhases(findings, profile, ctx);
  const GLOBAL = ['foundation-a', 'foundation-b', 'foundation', 'generic', 'global'];
  const phases = built.map((x, i) => {
    const title = x.area.name + (x.label ? ` (${x.label})` : '');
    const prev = old.phases.find((o) => o.title === title && o.files && o.files.length === x.files.length && o.files.join() === x.files.join());
    const mapped = route.routesFor(root, x.files, entries);
    const useMapped = mapped.length > 0 && !GLOBAL.includes(x.area.key);
    const routes = (useMapped ? mapped : defaults).slice(0, 3);
    const weak = x.area.key === 'pages' && !mapped.length;
    return { id: String(i + 1), title, area: x.area.key, kind: x.area.kind || 'fix', status: prev ? prev.status : 'todo', why: x.area.why, how: x.area.how, files: x.files, extraFiles: [], findings: x.findings.map((f) => f.id), renames: [], routes, weakCoverage: weak, risk: GLOBAL.includes(x.area.key) ? 'touches every page — full visual pass' : '', dependsOn: i ? [String(i)] : [] };
  });
  const plan = { domain: dom.name, generated: new Date().toISOString(), limits: { maxFiles: MAX_FILES, maxFindings: MAX_FINDINGS }, phases };
  u.writeJSON(dp.planJson, plan);
  const md = render(plan, byId);
  u.writeText(dp.plan, md);
  let rn = { count: 0, kept: 0 };
  if (dom.name === 'scss') {
    const phaseOf = {};
    for (const ph of phases) for (const id of ph.findings) phaseOf[id] = +ph.id;
    for (const k of libs.splitFindings(raw, lctx).kept) phaseOf[k.finding.id] = phaseOf[k.finding.id] || null;
    const filePhase = {};
    for (const ph of phases) for (const f of ph.files) filePhase[f] = Math.max(filePhase[f] || 0, +ph.id);
    rn = renames(raw, phaseOf, root, lctx, filePhase);
    u.writeText(dp.renames, rn.text);
  }
  return { phases: phases.length, lines: md.split('\n').length, renames: rn.count, kept: rn.kept };
}

function renderOnly(root, domain) {
  const dp = domains.paths(root, domain);
  const plan = u.readJSON(dp.planJson, null);
  if (!plan) throw new Error(`No .ui-guard/${domain}/plan.json — run plan.js --domain ${domain} first.`);
  const byId = Object.fromEntries((u.readJSON(dp.findings, []) || []).map((f) => [f.id, f]));
  u.writeText(dp.plan, render(plan, byId));
}

module.exports = { run, render, renderOnly, areaOf, buildPhases, parentBlock, MAX_FILES, MAX_FINDINGS };
if (require.main === module) {
  const args = u.parseArgs(process.argv.slice(2));
  u.helpExit(args, HELP);
  const root = args.root ? path.resolve(args.root) : (project.findRoot() || process.cwd());
  const dom = domains.fromArgs(args);
  if (args._[0] === 'render') { renderOnly(root, dom.name); console.log(`.ui-guard/${dom.name}/plan.md re-rendered from plan.json`); process.exit(0); }
  const r = run(root, dom.name);
  console.log(`plan → .ui-guard/${dom.name}/plan.md (${r.phases} phases, ${r.lines} lines) + plan.json${dom.name === 'scss' ? ` · renames → .ui-guard/scss/renames.md (${r.renames} row(s), ${r.kept} library class(es) kept)` : ''}`);
  console.log(require('./cleanup').finish(root, { ...args, domain: dom.name })); // last script of /ui-guard:scan: scratch cleanup, same rules
}
